    async function findAndCloseShareModal() {
        const modal = BrowserAdapter.query('div[role="dialog"], div.ds-modal, div[class*="modal"], div[class*="dialog"]');
        if (modal && BrowserAdapter.isVisible(modal)) {
            const mText = BrowserAdapter.getText(modal).toLowerCase();
            if (mText.indexOf('chia sẻ') !== -1 || mText.indexOf('share') !== -1 || mText.indexOf('sao chép') !== -1 || mText.indexOf('copy link') !== -1 || mText.indexOf('分享') !== -1) {
                console.warn('[KageVietSub NewChat] Phát hiện hộp thoại chia sẻ. Đang tự động đóng...');
                const closeBtn = modal.querySelector('button[aria-label*="close"], button[aria-label*="đóng"], .ds-modal__close, button');
                if (closeBtn) {
                    BrowserAdapter.click(closeBtn);
                } else if (typeof document !== 'undefined') {
                    document.dispatchEvent(new KeyboardEvent('keydown', { key: 'Escape', code: 'Escape', keyCode: 27, bubbles: true }));
                }
                await sleep(800);
                return true;
            }
        }
        return false;
    }

    async function createNewChat(maxAttempts = 3) {
        console.log('%c[KageVietSub NewChat] Bắt đầu quy trình tạo hội thoại mới...', 'color: #00d2ff; font-weight: bold;');

        for (let attempt = 1; attempt <= maxAttempts; attempt++) {
            if (currentSession.stopRequested) {
                console.log('[KageVietSub NewChat] Hủy tạo chat mới do người dùng yêu cầu dừng.');
                return false;
            }

            console.log(`[KageVietSub NewChat] Lần thử ${attempt}/${maxAttempts}:`);

            await findAndCloseShareModal();

            console.log('[KageVietSub NewChat] Bước 1: Đang tìm nút tạo chat mới theo cấu trúc chuẩn...');
            let newChatBtn = null;
            const findStart = Date.now();
            while (Date.now() - findStart < 4000) {
                newChatBtn = findNewChatButton();
                if (newChatBtn) break;
                await sleep(300);
            }

            if (!newChatBtn) {
                console.warn(`[KageVietSub NewChat] Lần ${attempt}: Không tìm thấy nút New Chat hợp lệ. Đang thử lại...`);
                await sleep(1000);
                continue;
            }

            const isVisible = (newChatBtn.offsetParent !== null || (newChatBtn.getClientRects && newChatBtn.getClientRects().length > 0));
            const isDisabled = (newChatBtn.getAttribute('aria-disabled') === 'true' || newChatBtn.hasAttribute('disabled'));

            if (!isVisible || isDisabled) {
                console.warn(`[KageVietSub NewChat] Lần ${attempt}: Nút New Chat đang bị ẩn hoặc disabled.`);
                await sleep(1000);
                continue;
            }

            console.log('[KageVietSub NewChat] Bước 2: Đã xác định chính xác nút New Chat:', newChatBtn);

            const initialUrl = window.location.href;
            const initialMsgCount = getAssistantMessageCount();

            console.log('[KageVietSub NewChat] Bước 3: Đang click vào nút New Chat...');
            try {
                if (typeof window !== 'undefined' && 'ontouchstart' in window) {
                    newChatBtn.dispatchEvent(new TouchEvent('touchstart', { bubbles: true, cancelable: true }));
                    newChatBtn.dispatchEvent(new TouchEvent('touchend', { bubbles: true, cancelable: true }));
                }
            } catch (e) {}
            clickButton(newChatBtn);

            console.log('[KageVietSub NewChat] Bước 4: Đang chờ giao diện hội thoại mới xuất hiện...');
            const waitStart = Date.now();
            let stateChanged = false;
            let shareModalOpened = false;

            while (Date.now() - waitStart < 6000) {
                if (currentSession.stopRequested) return false;

                if (await findAndCloseShareModal()) {
                    shareModalOpened = true;
                    break;
                }

                const curUrl = BrowserAdapter.getUrl();
                const curMsgCount = getAssistantMessageCount();
                const curInput = findChatInput();

                if (verifyNewChatReady(initialUrl, curUrl, initialMsgCount, curMsgCount, !!curInput)) {
                    stateChanged = true;
                    break;
                }
                await sleep(400);
            }

            if (shareModalOpened) {
                console.warn(`[KageVietSub NewChat] Lần ${attempt}: Đã đóng hộp thoại chia sẻ. Đang tìm lại chính xác nút New Chat...`);
                await sleep(1000);
                continue;
            }

            if (!stateChanged) {
                console.warn(`[KageVietSub NewChat] Lần ${attempt}: Trạng thái hội thoại chưa thay đổi sau khi click.`);
                await sleep(1000);
                continue;
            }

            console.log('[KageVietSub NewChat] Bước 5: Kiểm tra ô nhập tin nhắn...');
            await sleep(500);
            const finalInput = findChatInput();

            if (finalInput) {
                console.log('%c[KageVietSub NewChat] THÀNH CÔNG: Hội thoại mới và ô nhập tin nhắn đã sẵn sàng!', 'color: #10b981; font-weight: bold;');
                return true;
            } else {
                console.warn(`[KageVietSub NewChat] Lần ${attempt}: Ô nhập tin nhắn chưa sẵn sàng sau khi click.`);
                await sleep(1000);
            }
        }

        const errMsg = 'Không thể tạo cuộc trò chuyện mới trên DeepSeek sau 3 lần thử. Vui lòng kiểm tra lại giao diện.';
        console.error(`[KageVietSub NewChat] ${errMsg}`);
        updateUIStatus(`Lỗi: ${errMsg}`);
        throw new Error(errMsg);
    }

    async function sendMessageAndWaitConfirmation(textToSend, maxWaitMs = 8000) {
        const input = findChatInput();
        if (!input) {
            throw new Error('Không tìm thấy khung nhập tin nhắn của DeepSeek.');
        }

        setInputValue(input, textToSend);
        await sleep(500);

        const baselineCount = getAssistantMessageCount();
        const isDesktop = DeviceCompatibilityManager.isDesktop();

        if (isDesktop) {
            
            console.log('[KageVietSub Send] Thực thi cơ chế DESKTOP: Gửi bằng phím Enter...');
            sendViaKeyboardEnter(input);

            await sleep(1500);
            const curVal = (input.tagName.toLowerCase() === 'textarea' ? input.value : input.innerText) || '';
            if (curVal.length > 0 && !isAiGenerating() && !isAiThinking()) {
                console.log('[KageVietSub Send] Thử lại Enter lần 2 trên PC...');
                sendViaKeyboardEnter(input);
            }
        } else {
            
            console.log('[KageVietSub Send] Thực thi cơ chế MOBILE: Tìm và click nút gửi thực tế...');
            let sendBtn = null;
            const startFind = Date.now();
            while (Date.now() - startFind < 4000) {
                sendBtn = findSendButton();
                if (sendBtn) break;
                await sleep(200);
            }

            if (!sendBtn) {
                throw new Error('Nút gửi (Send button) chưa sẵn sàng hoặc không tìm thấy trên điện thoại.');
            }

            clickButton(sendBtn);
        }

        const startConfirm = Date.now();
        while (Date.now() - startConfirm < maxWaitMs) {
            if (currentSession.stopRequested) return false;

            const curInputVal = BrowserAdapter.getInputValue(input);
            const isGen = isAiGenerating();
            const isThk = isAiThinking();
            const curCount = getAssistantMessageCount();

            if (evaluateSendSuccess(baselineCount, curCount, isGen, isThk, curInputVal)) {
                return true;
            }
            await sleep(300);
        }

        return false;
    }

    class ResponseMonitor {
        constructor(options = {}) {
            this.onProgress = options.onProgress || null;
            this.timeoutSec = options.timeoutSec || 300;
            this.expectedCount = options.expectedCount || null;
            this.state = 'UNINITIALIZED'; 
            this.observer = null;
            this.observedContainer = null;
            this.baselineMsgCount = 0;
            this.firstMutationDetected = false;
            this.lastReportedText = '';
            this.lastMutationTime = 0;
            this.stableCount = 0;
            this.resolvePromise = null;
            this.rejectPromise = null;
            this.completionPromise = null;
            this.startTime = 0;
        }

        async init() {
            console.log('[MONITOR] Initializing response monitor');
            this.state = 'INITIALIZING';

            this.cleanup();

            const container = this.findResponseContainer();
            if (container) {
                this.observedContainer = container;
                console.log('[MONITOR] Response container detected');
            } else {
                this.observedContainer = (typeof document !== 'undefined') ? document.body : null;
                console.log('[MONITOR] Response container detected (fallback: body)');
            }

            this.baselineMsgCount = getAssistantMessageCount();

            this.createObserver();
            console.log('[MONITOR] MutationObserver registered');

            this.state = 'READY';
            console.log('[MONITOR] Monitor ready');
            return true;
        }

        findResponseContainer() {
            const selectors = [
                'div[class*="chat-scroll"]',
                'div[class*="chat-container"]',
                'div[class*="chat-main"]',
                'div[class*="message-list"]',
                'main',
                '#root'
            ];
            for (let i = 0; i < selectors.length; i++) {
                const el = BrowserAdapter.query(selectors[i]);
                if (el && BrowserAdapter.isVisible(el)) {
                    return el;
                }
            }
            return (typeof document !== 'undefined') ? document.body : null;
        }

        createObserver() {
            if (typeof MutationObserver === 'undefined') return;

            this.observer = new MutationObserver((mutations) => {
                if (this.state !== 'MONITORING' && this.state !== 'READY') return;

                if (!this.firstMutationDetected) {
                    this.firstMutationDetected = true;
                    console.log('[MONITOR] First response mutation detected');
                }

                this.lastMutationTime = Date.now();
                this.checkAndReportUpdate();
            });

            const target = this.observedContainer || ((typeof document !== 'undefined') ? document.body : null);
            if (target && target.nodeType) {
                try {
                    this.observer.observe(target, {
                        childList: true,
                        subtree: true,
                        characterData: true
                    });
                } catch (e) {
                    console.warn('[MONITOR] Failed to observe target, fallback to body:', e);
                }
            }
        }

        startMonitoring() {
            if (this.state === 'UNINITIALIZED' || !this.observer) {
                this.init();
            }
            this.state = 'MONITORING';
            this.startTime = Date.now();
            this.lastMutationTime = Date.now();
            this.firstMutationDetected = false;
            this.lastReportedText = '';
            this.stableCount = 0;

            this.completionPromise = new Promise((resolve, reject) => {
                this.resolvePromise = resolve;
                this.rejectPromise = reject;
            });

            this.startPollLoop();

            return this.completionPromise;
        }

        checkAndReportUpdate() {
            if (this.state !== 'MONITORING') return;

            const currentText = getLatestAssistantText();
            if (!currentText) return;

            if (currentText !== this.lastReportedText) {
                this.lastReportedText = currentText;
                this.lastMutationTime = Date.now();
                this.stableCount = 0;
                console.log('[MONITOR] Response content updated');
                if (this.onProgress) {
                    try {
                        this.onProgress(currentText);
                    } catch (e) {
                        console.error('[MONITOR] Error in onProgress callback:', e);
                    }
                }
            }
        }

        async startPollLoop() {
            while (this.state === 'MONITORING') {
                if (Date.now() - this.startTime > this.timeoutSec * 1000) {
                    this.finish(this.lastReportedText);
                    return;
                }

                if (currentSession && currentSession.stopRequested) {
                    this.finish(this.lastReportedText);
                    return;
                }

                if (checkAndClickContinue()) {
                    this.stableCount = 0;
                    this.lastMutationTime = Date.now();
                    await sleep(1000);
                    continue;
                }

                this.ensureContainerAttached();

                const isGen = isAiGenerating();
                const isThk = isAiThinking();
                const currentText = getLatestAssistantText();

                if (currentText && currentText !== this.lastReportedText) {
                    this.lastReportedText = currentText;
                    this.lastMutationTime = Date.now();
                    this.stableCount = 0;
                    console.log('[MONITOR] Response content updated');
                    if (this.onProgress) {
                        try {
                            this.onProgress(this.lastReportedText);
                        } catch (e) {
                            console.error('[MONITOR] Error in onProgress callback:', e);
                        }
                    }
                }

                const evalState = evaluateResponseProgress(
                    currentText,
                    this.lastReportedText,
                    isGen,
                    isThk,
                    this.stableCount,
                    CONFIG.STABLE_CHECKS_REQUIRED
                );

                if (evalState.action === 'LENGTH_LIMIT') {
                    this.state = 'ERROR';
                    this.cleanup();
                    if (this.rejectPromise) {
                        this.rejectPromise(new Error('DEEPSEEK_LENGTH_LIMIT'));
                    }
                    return;
                } else if (evalState.action === 'PROGRESS') {
                    this.lastReportedText = evalState.text;
                    this.lastMutationTime = Date.now();
                    this.stableCount = 0;
                    console.log('[MONITOR] Response content updated');
                    if (this.onProgress) {
                        try {
                            this.onProgress(this.lastReportedText);
                        } catch (e) {
                            console.error('[MONITOR] Error in onProgress callback:', e);
                        }
                    }
                } else if (evalState.action === 'COMPLETED') {
                    
                    if (this.expectedCount && this.lastReportedText) {
                        const parsedTemp = parseAiResponse(this.lastReportedText);
                        const parsedCount = Object.keys(parsedTemp).length;
                        const elapsedSinceMutation = Date.now() - (this.lastMutationTime || this.startTime);
                        if (parsedCount < this.expectedCount && elapsedSinceMutation < 3500) {
                            
                            await sleep(CONFIG.POLL_INTERVAL_MS);
                            continue;
                        }
                    }
                    this.finish(evalState.text || this.lastReportedText);
                    return;
                } else {
                    this.stableCount = evalState.stableCount;
                }

                await sleep(CONFIG.POLL_INTERVAL_MS);
            }
        }

        ensureContainerAttached() {
            if (typeof document === 'undefined') return;
            if (!this.observedContainer || !document.contains(this.observedContainer)) {
                console.log('[MONITOR] Response container replaced, re-attaching observer...');
                this.observedContainer = this.findResponseContainer();
                if (this.observer) {
                    try {
                        this.observer.disconnect();
                        this.observer.observe(this.observedContainer || document.body, {
                            childList: true,
                            subtree: true,
                            characterData: true
                        });
                    } catch (e) {}
                }
            }
        }

        finish(resultText) {
            if (this.state === 'COMPLETED') return;
            this.state = 'COMPLETED';
            console.log('[MONITOR] Response completed');
            this.cleanup();
            if (this.resolvePromise) {
                this.resolvePromise(resultText || this.lastReportedText);
            }
        }

        abort() {
            this.state = 'ABORTED';
            this.cleanup();
            if (this.resolvePromise) {
                this.resolvePromise(this.lastReportedText);
            }
        }

        cleanup() {
            if (this.observer && this.observer.disconnect) {
                try {
                    this.observer.disconnect();
                } catch (e) {}
            }
            this.observer = null;
        }
    }

    async function monitorAiResponse(onProgressText, timeoutSec = 300) {
        const monitor = new ResponseMonitor({
            onProgress: onProgressText,
            timeoutSec: timeoutSec
        });
        await monitor.init();
        return await monitor.startMonitoring();
    }

    async function recoverDeepSeekLengthLimit(batchItems, activePrompt, batchIdx, totalBatches) {
        console.warn('[KageVietSub Recovery] Kích hoạt quy trình phục hồi Length Limit chuẩn PC...');
        updateUIStatus('Phát hiện DeepSeek Length Limit! Đang tạo chat mới và nạp ngữ cảnh...');

        for (let attempt = 1; attempt <= 3; attempt++) {
            if (currentSession.stopRequested) return false;

            const missingItemsList = filterMissingItems(batchItems);

            if (missingItemsList.length === 0) {
                updateUIStatus('Khôi phục thành công! Đã dịch đủ các câu.');
                return true;
            }

            updateUIStatus(`Khôi phục lần ${attempt}/3: Mở chat mới cho ${missingItemsList.length} câu còn thiếu...`);
            const newChatOk = await createNewChat();
            if (!newChatOk) {
                await sleep(1500);
                continue;
            }
            await sleep(1500);

            const recStep = orchestrateRecoveryStep(batchItems, activePrompt);
            const recoveryMessage = (recStep && recStep.recoveryPrompt) ? recStep.recoveryPrompt : buildRecoveryPrompt(activePrompt, currentSession.lastCompletedItem, missingItemsList);

            const monitor = new ResponseMonitor({
                timeoutSec: CONFIG.POLL_TIMEOUT_SEC || 300
            });
            await monitor.init();

            console.log('[PROMPT] Sending prompt');
            const sent = await sendMessageAndWaitConfirmation(recoveryMessage);
            if (!sent) {
                monitor.abort();
                await sleep(1000);
                continue;
            }

            const resp = await monitor.startMonitoring();
            const missingSet = new Set(missingItemsList.map(it => it.id));
            const parsed = parseAiResponse(resp, missingSet);

            applyRecoveryResults(batchItems, parsed, currentSession.lastCompletedItem ? currentSession.lastCompletedItem.id : null);
            updateSessionProgress();
        }

        const stillMissing = filterMissingItems(batchItems);
        return stillMissing.length === 0;
    }

    async function processBatchWithRetries(batchItems, activePrompt, batchIdx, totalBatches) {
        const bStartId = batchItems[0].id;
        const bEndId = batchItems[batchItems.length - 1].id;

        updateUIStatus(`Đang dịch đoạn ${batchIdx}/${totalBatches}...`);

        currentSession.generationState = 'PREPARED';
        const batchStep = orchestrateBatchStep(currentSession, batchIdx - 1, activePrompt);
        const initialPrompt = (batchStep && batchStep.promptText) ? batchStep.promptText : buildBatchPrompt(activePrompt, batchItems);

        const monitor = new ResponseMonitor({
            onProgress: (text) => {
                currentSession.generationState = 'GENERATING';
                const partial = parseAiResponse(text, batchItems);
                const detectedCount = Object.keys(partial).length;
                console.log(`[MONITOR] Currently detected: ${detectedCount}/${batchItems.length}`);
                console.log('[MONITOR] Response is still generating. Waiting...');
                
                validateTranslationResults(batchItems, partial, true);
                updateSessionProgress();
            },
            timeoutSec: CONFIG.POLL_TIMEOUT_SEC || 300,
            expectedCount: batchItems.length
        });
        await monitor.init();

        console.log('[PROMPT] Sending first prompt');
        console.log(`[SEND] Submitted subtitles: ${bStartId}–${bEndId}`);
        const sent = await sendMessageAndWaitConfirmation(initialPrompt);
        if (!sent) {
            monitor.abort();
            throw new Error(`Không thể gửi batch ${batchIdx} vào DeepSeek.`);
        }
        currentSession.generationState = 'SUBMITTED';

        updateUIStatus(`Đang chờ DeepSeek trả lời đoạn ${batchIdx}/${totalBatches}...`);
        console.log('[GENERATION] DeepSeek is generating...');

        let responseText = '';
        try {
            responseText = await monitor.startMonitoring();
        } catch (err) {
            if (err.message === 'DEEPSEEK_LENGTH_LIMIT') {
                const recovered = await recoverDeepSeekLengthLimit(batchItems, activePrompt, batchIdx, totalBatches);
                if (!recovered) {
                    throw new Error(`Đoạn ${batchIdx} bị ngắt bởi Length Limit và không thể phục hồi.`);
                }
                saveSessionToStorage();
                return true;
            }
            throw err;
        }

        currentSession.generationState = 'RECEIVED';
        console.log('[GENERATION] Generation completed.');

        const parsedResults = parseAiResponse(responseText, batchItems);
        const valResults = validateTranslationResults(batchItems, parsedResults, false);
        console.log(`[VALIDATION] Received subtitles: ${valResults.completed.length}/${batchItems.length}`);

        let retryAttempt = 1;
        while (retryAttempt <= CONFIG.MAX_RETRIES && !currentSession.stopRequested) {
            const progress = evaluateBatchProgress(batchItems, CONFIG.MAX_RETRIES, retryAttempt);
            if (progress.isComplete) {
                break;
            }

            const missingItems = filterMissingItems(batchItems);
            const missingIds = missingItems.map(it => it.id);
            console.log(`[VALIDATION] Missing subtitles: ${missingIds.join(', ')}`);
            console.log(`[RECOVERY] Resending only missing range: ${missingItems.length} subtitles`);

            updateUIStatus(progress.statusMessage);
            await sleep(1500);

            const retryStep = orchestrateRetryStep(batchItems, missingIds, activePrompt, retryAttempt);
            const retryMessage = (retryStep && retryStep.retryPrompt) ? retryStep.retryPrompt : buildRetryPrompt(missingItems);

            const retryMonitor = new ResponseMonitor({
                timeoutSec: CONFIG.POLL_TIMEOUT_SEC || 300,
                expectedCount: missingItems.length
            });
            await retryMonitor.init();

            console.log(`[SEND] Resending missing prompt (attempt ${retryAttempt})`);
            const retrySent = await sendMessageAndWaitConfirmation(retryMessage);
            if (!retrySent) {
                retryMonitor.abort();
                retryAttempt++;
                continue;
            }

            let retryResponse = '';
            try {
                retryResponse = await retryMonitor.startMonitoring();
            } catch (err) {
                if (err.message === 'DEEPSEEK_LENGTH_LIMIT') {
                    await recoverDeepSeekLengthLimit(batchItems, activePrompt, batchIdx, totalBatches);
                    break;
                }
                throw err;
            }

            const retryParsed = parseAiResponse(retryResponse, missingItems);
            validateTranslationResults(missingItems, retryParsed, false);

            updateSessionProgress();
            retryAttempt++;
        }

        const finalProgress = evaluateBatchProgress(batchItems, CONFIG.MAX_RETRIES, retryAttempt);
        if (!finalProgress.isComplete) {
            throw new Error(`Đoạn ${batchIdx} còn thiếu ${finalProgress.missingCount} câu sau ${CONFIG.MAX_RETRIES} lần thử lại.`);
        }

        currentSession.generationState = 'COMMITTED';
        console.log(`[COMMIT] Batch ${batchIdx} (${bStartId}–${bEndId}) committed successfully.`);
        console.log(`[PROGRESS] Next subtitle: ${bEndId + 1}`);

        saveSessionToStorage();
        return true;
    }

    async function startTranslationProcess() {
        if (currentSession.isTranslating) {
            console.warn('[KageVietSub Pipeline] Tiến trình dịch đã đang chạy. Bỏ qua lệnh trùng lặp.');
            return;
        }

        if (!currentSession.items || currentSession.items.length === 0) {
            alert('Vui lòng chọn file phụ đề SRT trước.');
            return;
        }

        initBatchState(currentSession.items);

        DeviceCompatibilityManager.detect();

        const customPromptText = (uiElements.customPromptInput ? uiElements.customPromptInput.value : '').trim();
        const activePrompt = customPromptText || getDefaultPrompt();
        console.log(`[KageVietSub Prompt] Đang sử dụng: ${customPromptText ? 'PROMPT TÙY CHỈNH (In-memory)' : 'PROMPT GỐC CỦA TOOL PC'}`);

        const totalItems = currentSession.items.length;
        const mode = userSettings.mode;
        let batchSize = userSettings.batchSize;

        if (mode === 'all') {
            batchSize = totalItems;
            const totalChars = currentSession.items.reduce((sum, it) => sum + it.original.length, 0);

            if (totalItems > CONFIG.SAFE_FULL_MODE_ITEMS || totalChars > CONFIG.SAFE_FULL_MODE_CHARS) {
                const confirmMsg = `CẢNH BÁO: File có ${totalItems.toLocaleString('vi-VN')} dòng phụ đề (~${totalChars.toLocaleString('vi-VN')} ký tự).\n\n` +
                    `Gửi toàn bộ trong 1 lần vượt ngưỡng tối ưu của DeepSeek, dễ dẫn đến bị ngắt câu hoặc lỗi giới hạn độ dài.\n\n` +
                    `Bạn có muốn tiếp tục gửi toàn bộ không?\n` +
                    `• Nhấn [OK] để tiếp tục gửi toàn bộ.\n` +
                    `• Nhấn [Cancel] để quay lại và chọn 'Gửi theo số dòng' (khuyên dùng 50-100 dòng/lần).`;
                if (!confirm(confirmMsg)) {
                    updateUIStatus('Đã hủy gửi toàn bộ. Vui lòng chọn chế độ chia đoạn.');
                    return;
                }
            }
        }

        currentSession.mode = mode;
        currentSession.batchSize = batchSize;
        currentSession.selectedBatchSize = batchSize;
        currentSession.isTranslating = true;
        currentSession.stopRequested = false;
        updateUIState(true);

        const batchPlan = calculateBatches(currentSession.items, currentSession.mode, currentSession.batchSize);
        const totalBatches = batchPlan.totalBatches;
        currentSession.totalBatches = totalBatches;

        console.log(`[BATCH] Selected batch size: ${currentSession.batchSize}`);
        console.log(`[BATCH] Total batches: ${totalBatches}, Total items: ${totalItems}`);

        try {
            updateUIStatus('Đang kiểm tra giao diện DeepSeek...');

            if (DeviceCompatibilityManager.isMobile() && currentSession.currentBatchIndex === 0) {
                const initialMsgCount = getAssistantMessageCount();
                if (initialMsgCount > 0) {
                    updateUIStatus('Đang tạo cuộc trò chuyện mới trên điện thoại...');
                    console.log('[CHAT] Creating a new conversation for mobile start...');
                    await createNewChat();
                    console.log('[CHAT] New conversation confirmed.');
                    await sleep(1500);
                }
            }

            const input = findChatInput();
            if (!input) {
                throw new Error('Không tìm thấy khung nhập tin nhắn của DeepSeek. Vui lòng kiểm tra đã đăng nhập chưa.');
            }

            for (let b = currentSession.currentBatchIndex; b < totalBatches; b++) {
                if (currentSession.stopRequested) {
                    const pipeStop = evaluatePipelineNext(currentSession, false, true);
                    updateUIStatus(pipeStop ? pipeStop.statusMessage : 'Đã dừng tiến trình dịch.');
                    break;
                }

                currentSession.currentBatchIndex = b;
                const batchItems = batchPlan.batches[b].items;
                const bStartId = batchItems[0].id;
                const bEndId = batchItems[batchItems.length - 1].id;

                if (batchItems.every(it => it.status === 'completed' && it.translated)) {
                    console.log(`[COMMIT] Batch ${b + 1}/${totalBatches} (${bStartId}–${bEndId}) đã hoàn thành đầy đủ. Tiếp tục đoạn kế tiếp.`);
                    continue;
                }

                console.log(`[BATCH] Prepared subtitles: ${bStartId}–${bEndId} (${batchItems.length} subtitles)`);
                await processBatchWithRetries(batchItems, activePrompt, b + 1, totalBatches);

                const pipeNext = evaluatePipelineNext(currentSession, false, currentSession.stopRequested);
                if (pipeNext && pipeNext.action === 'NEXT_BATCH') {
                    if (b + 1 < totalBatches && !currentSession.stopRequested) {
                        updateUIStatus(`Đang tạo cuộc trò chuyện mới cho đoạn ${b + 2}/${totalBatches}...`);
                        console.log('[CHAT] Creating a new conversation...');
                        await createNewChat();
                        console.log('[CHAT] New conversation confirmed.');
                        console.log(`[BATCH] Next batch: ${batchPlan.batches[b + 1].items[0].id}–${batchPlan.batches[b + 1].items[batchPlan.batches[b + 1].items.length - 1].id}`);
                        await sleep(2000);
                    }
                }
            }

            const missingTotal = currentSession.items.filter(it => it.status !== 'completed');
            if (missingTotal.length === 0 && !currentSession.stopRequested) {
                updateUIStatus('Đang xác thực và tạo file phụ đề hoàn chỉnh...');
                await sleep(500);
                downloadTranslatedSrt();
                updateUIStatus('Hoàn thành! Đã tự động tải file SRT.');
                clearSessionStorage();
            } else if (!currentSession.stopRequested) {
                updateUIStatus(`Dịch chưa xong: Còn thiếu ${missingTotal.length} câu.`);
                alert(`Không thể xuất file: Còn ${missingTotal.length} câu chưa hoàn thành dịch.`);
            }

        } catch (error) {
            console.error('[KageVietSub Error]', error);
            updateUIStatus(`Lỗi: ${error.message || error}`);
            alert(`Lỗi trong quá trình dịch: ${error.message || error}`);
        } finally {
            currentSession.isTranslating = false;
            updateUIState(false);
        }
    }

    function downloadTranslatedSrt() {
        const validation = validateFinalExport(currentSession.items);
        if (!validation.valid) {
            alert(`Lỗi kiểm tra tính toàn vẹn phụ đề: ${validation.reason}`);
            return;
        }

        const srtContent = buildCompleteSrtContent(currentSession.items);
        let baseName = currentSession.fileName || 'phu_de';
        if (baseName.toLowerCase().endsWith('.srt')) {
            baseName = baseName.substring(0, baseName.length - 4);
        }
        baseName = baseName.replace(/_dich(_\d+)?$/i, '');
        const outputName = `${baseName}_dich.srt`;

        const blob = new Blob([srtContent], { type: 'text/plain;charset=utf-8' });
        const url = URL.createObjectURL(blob);
        const a = document.createElement('a');
        a.href = url;
        a.download = outputName;
        document.body.appendChild(a);
        a.click();
        setTimeout(() => {
            document.body.removeChild(a);
            URL.revokeObjectURL(url);
        }, 2000);
    }

    function downloadSamplePrompt() {
        const sampleText = getSamplePromptText();
        const blob = new Blob([sampleText], { type: 'text/plain;charset=utf-8' });
        const url = URL.createObjectURL(blob);
        const a = document.createElement('a');
        a.href = url;
        a.download = 'KAGEVIETSUB_PROMPT_MAU.txt';
        document.body.appendChild(a);
        a.click();
        setTimeout(() => {
            document.body.removeChild(a);
            URL.revokeObjectURL(url);
        }, 2000);
    }

    function saveSessionToStorage() {
        const serialized = serializeSessionLogic(currentSession);
        if (serialized) {
            StorageAdapter.set(CONFIG.STORAGE_KEY, serialized);
        }
    }

    function loadSessionFromStorage() {
        const raw = StorageAdapter.get(CONFIG.STORAGE_KEY, null);
        const res = deserializeSessionLogic(raw, userSettings.batchSize);
        return (res && res.valid) ? res.session : null;
    }

    function clearSessionStorage() {
        StorageAdapter.remove(CONFIG.STORAGE_KEY);
    }

